from enum import Enum
from typing import Dict, Optional

class GhostState(str, Enum):
    CHASE = 'chase'
    AMBUSH = 'ambush'
    PATROL = 'patrol'
    RANDOM = 'random'
    FLEE = 'flee'
    EATEN = 'eaten'

class GhostIdentity(str, Enum):
    BLINKY = 'Blinky'
    PINKY = 'Pinky'
    INKY = 'Inky'
    CLYDE = 'Clyde'

class Ghost:
    def __init__(self, identity: GhostIdentity, state: GhostState = GhostState.CHASE):
        self.identity = identity
        self.state = state

    def set_state(self, new_state: GhostState):
        self.state = new_state

    def get_state(self) -> GhostState:
        return self.state

class GhostManager:
    def __init__(self, start_positions: Optional[Dict[GhostIdentity, Dict[str, int]]] = None):
        self.ghosts = {identity: Ghost(identity) for identity in GhostIdentity}
        self.positions = start_positions or {}

    def set_ghost_state(self, identity: GhostIdentity, state: GhostState):
        if identity in self.ghosts:
            self.ghosts[identity].set_state(state)

    def get_ghost_state(self, identity: GhostIdentity) -> GhostState:
        if identity in self.ghosts:
            return self.ghosts[identity].get_state()
        return GhostState.CHASE

    def get_all_states(self) -> Dict[str, str]:
        return {ghost.identity.value: ghost.state.value for ghost in self.ghosts.values()}


